beforeExample:
public class Example { 
    public void test(int value) {
        java.lang.Integer i = new java.lang.Integer(value);
        System.out.println(i);
    }
}

afterExample:
public class Example { 
    public void test(int value) {
        java.lang.Integer i = java.lang.Integer.valueOf(value);
        System.out.println(i);
    }
}

negativeExample:
public class Example { 
    public void test(long value) {
        // Should not match new Long(value)
        java.lang.Long l = new java.lang.Long(value);
        System.out.println(l);
    }
}
